create table RB_LIMIT_SCENE_DEF (LIMIT_SCENE_NO VARCHAR(50) not null  ,LIMIT_SCENE_DESC VARCHAR(200) null  ,LIMIT_MAIN_TYPE VARCHAR(10) null  ,CHECK_OBJ_TYPE VARCHAR(10) null  ,LIMIT_CONVERT VARCHAR(1) null  ,LIMIT_CCY VARCHAR(3) null  ,VALID_FLAG VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(LIMIT_SCENE_NO));